export interface MountPoint {
  readonly route: string;
  readonly directory: string;
}

export interface GatewayOptions {
  readonly allowOrigin: string;
  readonly listenPort: number;
  readonly mounts: readonly MountPoint[];
}

export type GatewayOverrides = Partial<GatewayOptions>;

export function makeGatewayOptions(overrides: GatewayOverrides = {}): GatewayOptions {
  const listenPort = overrides.listenPort || 6688;
  if (!Number.isInteger(listenPort) || listenPort < 0 || listenPort > 65535) {
    throw new RangeError("Invalid port");
  }
  return {
    allowOrigin: overrides.allowOrigin ?? "*",
    listenPort,
    mounts: (overrides.mounts ?? []).map((mount) => ({ ...mount })),
  };
}
```

