import { makeGatewayOptions } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function assertJson(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const defaultsOne = makeGatewayOptions();
const defaultsTwo = makeGatewayOptions();
assertJson(defaultsOne, { allowOrigin: "*", listenPort: 6688, mounts: [] }, "default values");
assert(defaultsOne !== defaultsTwo, "fresh default options objects");
assert(defaultsOne.mounts !== defaultsTwo.mounts, "fresh default mount arrays");

const mounts = [
  { route: "/one", directory: "/srv/one" },
  { route: "/two", directory: "/srv/two" },
];
const overrides = { allowOrigin: "", listenPort: 0, mounts };
const result = makeGatewayOptions(overrides);
assertJson(result, { allowOrigin: "", listenPort: 0, mounts: [
  { route: "/one", directory: "/srv/one" },
  { route: "/two", directory: "/srv/two" },
] }, "falsy supplied values and mount order");
assert(result.mounts !== mounts, "mount array defensively copied");
assert(result.mounts[0] !== mounts[0], "mount objects defensively copied");
mounts[0].route = "/changed";
assert(result.mounts[0].route === "/one", "later override mutation cannot affect result");

for (const port of [-1, 65536, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  let threw = false;
  try {
    makeGatewayOptions({ listenPort: port });
  } catch (error: unknown) {
    threw = error instanceof RangeError && error.message === "Invalid port";
  }
  assert(threw, "invalid port must throw specified RangeError: " + String(port));
}
assert(makeGatewayOptions({ listenPort: 65535 }).listenPort === 65535, "upper port boundary");

